return [{json:{html:'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>'+title+'</title><style>body{font:16px system-ui;background:#f3f4f6;color:#20242a;max-width:760px;margin:40px auto;padding:24px}main{background:white;padding:32px;border-radius:12px}label{display:block;margin:20px 0}input,textarea{box-sizing:border-box;display:block;width:100%;padding:12px;margin-top:8px;border:1px solid #bbc0c7;border-radius:6px;font:inherit}textarea{font:14px monospace}button{background:#ea580c;color:white;border:0;border-radius:6px;padding:14px 24px;font:inherit}</style></head><body><main><h1>'+title+'</h1><p>'+description+'</p><form method="post" action="'+esc(action)+'">'+inputs+'<button type="submit">'+(recover?'Recover this job':'Create one draft')+'</button></form></main></body></html>'}}];

const item=$input.first(),row=item.json,cfg=$('Apply video configuration').first().json.config;
const c=JSON.parse(row.contextJson),response=row._response;
if(c.stage!=='video'||response?.error||!response?.qc||!item.binary?.data)throw Error('A verified original MP4 is required for Dropbox');
if(!/^video-[0-9]+$/.test(row.jobId)||!/^[a-f0-9]{64}$/.test(response.sha256||'')||response.qc.width!==1080||response.qc.height!==1920||!Number.isFinite(response.qc.duration)||response.qc.duration<3||response.qc.duration>60||!Number.isSafeInteger(response.size)||response.size<1024||response.size>40*1024*1024)throw Error('The completed MP4 failed the Dropbox archive checks');
const folder=String(cfg.dropboxFolder||'').replace(/\/+$/,'');
if(!folder.startsWith('/')||folder.length>300||/[\x00-\x1f\\]/.test(folder)||folder.split('/').some(p=>p==='.'||p==='..'))throw Error('Configure an absolute Dropbox folder without relative path segments');
const fileName=row.jobId+'-'+response.sha256.slice(0,16)+'.mp4',path=folder+'/'+fileName;
return [{json:{...row,_dropboxUpload:{path,sha256:response.sha256,size:response.size}},binary:{data:{...item.binary.data,fileName,mimeType:'video/mp4'}}}];

const original=$('Prepare Dropbox MP4').item.json,expected=original._dropboxUpload,result=$input.first().json;
const id=result.id,path=result.path_display||result.path_lower,contentHash=result.content_hash;
if(result.error||!id||!path||path.toLowerCase()!==expected.path.toLowerCase()||Number(result.size)!==expected.size||!/^[a-f0-9]{64}$/.test(contentHash||'')){
 const error='Dropbox archive upload failed: '+String(result.error?.message||result.error||'The uploaded file receipt did not match the original MP4').slice(0,1000);
 return [{json:{...original,_dropboxReceipt:{state:'failed',path:expected.path,sha256:expected.sha256,error,at:new Date().toISOString()},_response:{error:{message:error}}}}];
}
return [{json:{...original,_dropboxReceipt:{state:'uploaded',id,path,rev:result.rev||null,contentHash,sha256:expected.sha256,size:Number(result.size),at:new Date().toISOString()}}}];
